package com.jb.radar;
public class InterceptionTest {
 static void check(boolean b,String s){if(!b)throw new AssertionError(s);}
 static Game.EnemyMissile incoming(Game g,int weapon){Game.EnemyMissile m=new Game.EnemyMissile();m.id=101;m.weapon=weapon;m.x=8;m.y=0;m.z=3;m.alt=3000;m.px=8;m.palt=3000;m.samples=3;m.seen=g.elapsed;m.source=GameTest.target(g,0);g.enemyMissiles.add(m);return m;}
 public static void main(String[] args){for(int weapon=0;weapon<5;weapon++){Game g=new Game(4);g.start();g.contacts.clear();Game.EnemyMissile e=incoming(g,weapon);check(g.nextTarget(null)==e,"missile participates in distance cycle");g.track(e);g.illuminate(e);check(g.channels()==1,"missile consumes shared channel");Game.Contact a=GameTest.target(g,1),b=GameTest.target(g,2);g.illuminate(a);g.illuminate(b);check(g.channels()==2&&!b.illuminated,"mixed channel cap");g.launch(e);check(g.shots==1,"launch at missile");Game.Missile m=g.missiles.get(0);for(int i=0;i<1000&&m.alive;i++){g.elapsed+=.02;g.fly(m,.02);if(e.alive)g.flyEnemy(e,.02);}check(!e.alive&&g.kills==1&&g.radarHits==0,"moving missile intercepted weapon "+weapon);check(g.channels()==1,"channel freed on intercept");}
 Game g=new Game(1);g.start();Game.EnemyMissile m=incoming(g,4);m.samples=1;check(g.identity(m)==0,"unknown missile");m.samples=2;check(g.identity(m)==1,"enemy uncertain type");m.samples=3;check(g.identity(m)==2,"known enemy missile");g.elapsed=9;check(g.identity(m)==0,"stale ID");for(int i=1;i<=4;i++){g.damageRadar();check(g.hitsRemaining()==4-i,"hit counter");check(g.finished==(i==4),"fourth impact defeats base");}g.start();check(g.hitsRemaining()==4,"reset hit limit");System.out.println("PASS: intercept all five moving missile types, shared channels, mixed target cycling, ID transitions and four-hit defeat");}
}
